// Build request: turns simple commands into MCS-8M frames.
//   {read:"program"} {read:"preset"} {read:"aux", aux:1}
//   {read:"mute", ch:1..6} {read:"faders"}
//   {aux:1|2, source:1..14}   <- WRITE: changes the Aux output
const FID = 0x50;
function frame(pid, tid, msg) {
    const p = [pid, FID, tid, 0, 0, ...msg];
    const body = [(p.length >> 8) & 0xff, p.length & 0xff, ...p];      // BC is BIG-endian
    const cs = (0x100 - (body.reduce((a, b) => a + b, 0) & 0xff)) & 0xff;
    return Buffer.from([0x01, 0x02, ...body, cs, 0x03]);
}
const video = (eff, cmd, ...a) => frame(0x01, 0x20, [0x03, 2 + a.length, eff, cmd, ...a]);
const audio = (cmd, ...d) => frame(0x02, 0x30, [cmd, ...d]);

const q = msg.payload || {};
let out;
if (q.read === 'program') out = video(0x00, 0x00);
else if (q.read === 'preset') out = video(0x00, 0x01);
else if (q.read === 'aux' && (q.aux === 1 || q.aux === 2)) out = video(q.aux + 1, 0x00);
else if (q.read === 'mute' && q.ch >= 1 && q.ch <= 6) out = audio(0x93, q.ch - 1, 0);
else if (q.read === 'faders') out = audio(0x90, 0, 0, 0, 0, 0, 0, 0, 0);
else if ((q.aux === 1 || q.aux === 2) && Number.isInteger(q.source) && q.source >= 1 && q.source <= 14)
    out = video(q.aux + 1, 0x80, 0x00, q.source);                        // WRITE
if (!out) { node.warn('unknown request: ' + JSON.stringify(q)); return null; }
msg.payload = out;
return msg;

// Parse MCS-8M frames. The serial-in node may deliver frames in pieces, or
// several at once, so we buffer and cut frames by BC - never by 0x03.
let buf = context.get('buf') || Buffer.alloc(0);
buf = Buffer.concat([buf, msg.payload]);
const out = [];
while (buf.length) {
    if (buf[0] !== 0x01) { buf = buf.subarray(1); continue; }       // ACK (04) or noise
    if (buf.length < 4) break;
    const bc = (buf[2] << 8) | buf[3];
    if (buf[1] !== 0x02 || bc < 5 || bc > 512) { buf = buf.subarray(1); continue; }
    if (buf.length < bc + 6) break;                                    // wait for the rest
    const f = buf.subarray(0, bc + 6);
    let sum = 0; for (let i = 2; i < f.length - 1; i++) sum += f[i];
    if (f[f.length - 1] !== 0x03 || (sum & 0xff) !== 0) { buf = buf.subarray(1); continue; }
    buf = buf.subarray(bc + 6);

    const m = f.subarray(9, f.length - 2);
    const r = { raw: Buffer.from(f).toString('hex') };
    if (f[4] === 0x01) {                                              // video
        Object.assign(r, { kind: 'video', eff: m[2], cmd: m[3] & 0x7f, data: [...m.subarray(4)] });
        const sec = { 0: 'me', 2: 'aux1', 3: 'aux2' }[r.eff];
        if (sec && r.cmd === 0x00) { r.topic = sec === 'me' ? 'program' : sec; r.value = r.data[1]; }
        else if (sec === 'me' && r.cmd === 0x01) { r.topic = 'preset'; r.value = r.data[1]; }
        else if (r.eff === 0x20 && r.cmd === 0x37) { r.topic = 'transition'; r.value = r.data[2] === 1; }
    } else {                                                          // audio
        Object.assign(r, { kind: 'audio', cmd: m[0] & 0x7f, data: [...m.subarray(1)] });
        if (r.cmd === 0x13) { r.topic = 'mute.ch' + (r.data[0] + 1); r.value = r.data[1] === 1; }  // 1 = muted
        else if (r.cmd === 0x10) { r.topic = 'faders'; r.value = r.data; }
    }
    out.push({ topic: r.topic || 'other', payload: r });
}
context.set('buf', buf.length > 1024 ? Buffer.alloc(0) : buf);
const last = out.filter(o => o.topic !== 'other').pop();
if (last) node.status({ text: `${new Date().toLocaleTimeString()} ${last.topic} = ${JSON.stringify(last.payload.value)}` });
return out.length ? [out] : null;
